button { font: inherit; }
textarea { resize: vertical; }
input:focus, textarea:focus, select:focus { border-color: rgba(37,99,235,.5); }
.drag-over { border-color: rgba(37,99,235,.45) !important; background: rgba(37,99,235,.04) !important; }

.admin-shell {
  display: grid;
  grid-template: var(--topbar-height) minmax(0, 1fr) / var(--sidebar-expanded) minmax(0, 1fr);
  width: 100vw;
  height: 100dvh;
  overflow: hidden;
  background: var(--bg);
}
.admin-shell[data-sidebar="collapsed"] { grid-template-columns: var(--sidebar-collapsed) minmax(0, 1fr); }
.admin-shell[data-focus-mode="true"] { grid-template-columns: 0 minmax(0, 1fr); }
.admin-sidebar {
  grid-row: 1 / 3;
  z-index: 30;
  display: flex;
  min-width: 0;
  flex-direction: column;
  overflow: hidden;
  padding: 12px 10px;
  background: #18191c;
  border-right: 1px solid var(--b1);
  transition: width 180ms ease, transform 180ms ease, opacity 180ms ease;
.admin-install-primary, .admin-app-status button { display: inline-flex; gap: 8px; align-items: center; min-height: 44px; padding: 10px 14px; border: 0; border-radius: 6px; background: var(--acc); color: #18191c; cursor: pointer; }
.admin-app-status { position: fixed; z-index: 60; bottom: 16px; right: 16px; display: flex; flex-wrap: wrap; gap: 8px; max-width: calc(100vw - 32px); padding: 10px; border: 1px solid var(--b2); border-radius: 6px; background: var(--s1); font-size: 13px; }
.admin-main {
  grid-column: 2;
  grid-row: 2;
  min-width: 0;
  min-height: 0;
  overflow-x: hidden;
  overflow-y: auto;
  padding: 24px;
}
.admin-shell[data-forge-route="true"] .admin-main { overflow: hidden; padding: 0; }
.skip-link { position: fixed; z-index: 100; left: 16px; top: 8px; transform: translateY(-150%); border-radius: 8px; padding: 8px 12px; background: #fff; color: #111827; }
import type { Metadata } from "next"
import "./globals.css"
import { InstallAppProvider } from "@/components/command-centre/InstallAppProvider"
import { HydrationMarker } from "@/components/admin-shell/HydrationMarker"
import type { Viewport } from "next"

export const metadata: Metadata = {
  title: { default: "ScaleSmiths Admin", template: "%s | Admin" },
  robots: { index: false, follow: false },
  manifest: "/manifest.webmanifest",
  appleWebApp: {
    capable: true,
    title: "ScaleSmiths",
    statusBarStyle: "black-translucent",
  },
  icons: { icon: "/brand/favicon.png", shortcut: "/brand/favicon.png", apple: "/brand/favicon.png" },
}
export const viewport: Viewport = {
  width: "device-width",
  initialScale: 1,
  themeColor: "#111214",
}

export default function RootLayout({
  children,
}: {
  children: React.ReactNode
}) {
  return (
    <html lang="en">
      <body className="bg-bg text-t1">
        <HydrationMarker />
        <InstallAppProvider>{children}</InstallAppProvider>
      </body>
    </html>
  )
}
